-- L63 (KNW-1, KNW-6): the guides knowledge base. `repair_guides` is curated content:
-- every signed-in user reads it, only the pipeline and owner curations write it
-- (service_role bypasses RLS). Ships with 32 guides over the seeded enthusiast platforms.
-- `variant_id` mirrors `cars.catalog_variant_id`: a plain bigint key into the bundled
-- catalog snapshot, no FK (the catalog is not a database table).

create table public.repair_guides (
  id               uuid primary key default gen_random_uuid(),
  task             text not null check (char_length(task) between 3 and 120),
  make             text not null check (char_length(make) between 1 and 40),
  model            text check (char_length(model) between 1 and 60),
  variant_id       bigint,
  difficulty       int not null check (difficulty between 1 and 5),
  time_min_minutes int not null check (time_min_minutes > 0),
  time_max_minutes int not null check (time_max_minutes >= time_min_minutes),
  tools            jsonb not null default '[]' check (jsonb_typeof(tools) = 'array'),
  parts            jsonb not null default '[]' check (jsonb_typeof(parts) = 'array'),
  steps            jsonb not null check (jsonb_typeof(steps) = 'array' and jsonb_array_length(steps) >= 1),
  tradeoffs        text,
  mistakes         text,
  sources          jsonb not null check (jsonb_typeof(sources) = 'array' and jsonb_array_length(sources) >= 1),
  linked_mod_ids   jsonb not null default '[]' check (jsonb_typeof(linked_mod_ids) = 'array'),
  created_at       timestamptz not null default now()
);

alter table public.repair_guides enable row level security;

create policy repair_guides_read on public.repair_guides
  for select to authenticated using (true);

revoke all on public.repair_guides from public, anon;
grant select on public.repair_guides to authenticated;

create trigger suspended_write_guard before insert or update on public.repair_guides
  for each row execute function public.suspended_write_guard();

-- Curated seeds (KNW-6): oil/brakes/fluids, intake/exhaust/tune installs, suspension.
insert into public.repair_guides
  (task, make, model, difficulty, time_min_minutes, time_max_minutes, tools, parts, steps, tradeoffs, mistakes, sources, linked_mod_ids)
values
  ('Engine oil and filter change', 'Honda', 'S2000', 1, 45, 90,
   '["17mm socket","ratchet","oil filter wrench","torque wrench","drain pan","jack and stands","funnel"]'::jsonb,
   '[{"name":"5.1 qt 10W-30 synthetic oil","est_cost_cents_low":4500,"est_cost_cents_high":7000,"part_number":null},{"name":"Oil filter","est_cost_cents_low":800,"est_cost_cents_high":1400,"part_number":"15400-PCX-004"},{"name":"Crush washer 14mm","est_cost_cents_low":100,"est_cost_cents_high":300,"part_number":"94109-14000"}]'::jsonb,
   '["Warm the engine for five minutes, then lift the front on stands.","Remove the 17mm drain bolt and let the oil drain fully.","Spin the old filter off; oil the new filter gasket and hand-tighten it.","Refit the drain bolt with a new crush washer, torqued to 29 lb-ft.","Fill with 5.1 qt of 10W-30, run the engine for a minute, check for leaks.","Check the dipstick and top to the upper mark."]'::jsonb,
   'OEM filter costs a little more; quality aftermarket filters are fine. 5W-40 is a popular track-day swap but thickens cold starts.',
   'Over-tightening the drain bolt strips the pan threads. Forgetting the crush washer leaves a slow drip.',
   '["https://www.s2ki.com/forums/s2000-talk-1/","https://haynes.com/en-us/honda/s2000"]'::jsonb,
   '[]'::jsonb),

  ('Engine oil and filter change', 'Subaru', 'WRX', 1, 40, 80,
   '["14mm socket","ratchet","oil filter wrench","drain pan","jack and stands","funnel"]'::jsonb,
   '[{"name":"5.4 qt 5W-30 synthetic oil","est_cost_cents_low":4000,"est_cost_cents_high":6500,"part_number":null},{"name":"Oil filter","est_cost_cents_low":700,"est_cost_cents_high":1200,"part_number":"15208AA21A"},{"name":"Crush washer","est_cost_cents_low":100,"est_cost_cents_high":300,"part_number":"11126AA000"}]'::jsonb,
   '["Warm the engine, remove the undertray, and lift the front.","Remove the 14mm drain plug and drain fully.","The FA24 filter sits up top behind the intake; swap it from above.","Refit the plug with a new crush washer, 30 lb-ft.","Fill 5.4 qt, idle a minute, check the level and for leaks."]'::jsonb,
   'Subaru sells oil change kits cheap; dealer filters are a known-good baseline.',
   'The undertray bolts are easy to cross-thread. Do not overfill: the FA24 reads high on the dipstick quickly.',
   '["https://forums.nasioc.com/","https://www.clubwrx.net/"]'::jsonb,
   '[]'::jsonb),

  ('Engine oil and filter change', 'Volkswagen', 'Golf GTI', 1, 45, 90,
   '["T30 Torx","19mm socket","oil filter housing socket 32mm","drain pan","jack and stands","funnel"]'::jsonb,
   '[{"name":"5.7 qt VW 508 00 0W-20 oil","est_cost_cents_low":5000,"est_cost_cents_high":8000,"part_number":null},{"name":"Filter element and O-ring","est_cost_cents_low":1000,"est_cost_cents_high":1800,"part_number":"06L115562B"}]'::jsonb,
   '["Remove the T30 undertray fasteners and drop the tray.","Loosen the 32mm filter housing cap two turns and let oil drain back.","Remove the 19mm drain plug and drain fully.","Swap the element, fit the new O-ring, torque the cap to 20 Nm.","Refit the plug with a new seal, fill 5.7 qt, check the dipstick."]'::jsonb,
   'The EA888 takes a cartridge filter up top, so no mess under the car. Use only VW 508 00 spec oil on 2019+ cars.',
   'Reusing the drain-plug seal leaks. Torque the plastic filter cap by spec, not by feel.',
   '["https://www.vwvortex.com/","https://www.golfmk7.com/"]'::jsonb,
   '[]'::jsonb),

  ('Engine oil and filter change', 'BMW', 'M3', 1, 60, 120,
   '["17mm socket","36mm socket for filter cap","torque wrench","drain pan","jack and stands","funnel"]'::jsonb,
   '[{"name":"8.5 qt 10W-60 synthetic oil","est_cost_cents_low":11000,"est_cost_cents_high":16000,"part_number":null},{"name":"Filter kit with O-rings","est_cost_cents_low":2000,"est_cost_cents_high":3500,"part_number":"11427833769"}]'::jsonb,
   '["Warm the engine and lift the front of the E46 level.","Remove the 36mm filter cap under the intake, pull the element.","Remove the 17mm drain plug and drain fully.","Fit the new element and O-rings, torque the cap to 25 Nm.","Refit the plug, fill 8.5 qt of 10W-60, idle and check level via the gauge."]'::jsonb,
   'The S54 specifies 10W-60, which is pricier than common weights. Stick with it; thinner oil shortens rod-bearing life.',
   'The S54 has two small filter-housing O-rings that are easy to drop. Check the oil-level light with the car level.',
   '["https://www.e46fanatics.com/","https://www.bimmerforums.com/forum/"]'::jsonb,
   '[]'::jsonb),

  ('Front brake pads and rotors', 'Honda', 'S2000', 2, 90, 180,
   '["17mm socket","14mm socket","ratchet","torque wrench","C-clamp or piston tool","brake cleaner","jack and stands","wire brush"]'::jsonb,
   '[{"name":"Front pad set","est_cost_cents_low":6000,"est_cost_cents_high":14000,"part_number":"45022-S2A-000"},{"name":"Front rotor pair","est_cost_cents_low":9000,"est_cost_cents_high":20000,"part_number":"45251-S2A-000"},{"name":"Dot 3/4 brake fluid, small bottle","est_cost_cents_low":600,"est_cost_cents_high":1200,"part_number":null}]'::jsonb,
   '["Crack the lug nuts, lift the front, remove both wheels.","Remove the two 14mm caliper slide bolts and swing the caliper up; hang it with wire, never by the hose.","Unbolt the 17mm caliper bracket and lift the rotor off; clean the hub face.","Compress the piston with the old pad and a C-clamp.","Fit new hardware, pads, and rotor; torque bracket bolts to 80 lb-ft and slides to 25 lb-ft.","Pump the pedal until firm before driving; bed pads with six 40-10 mph stops."]'::jsonb,
   'Blank rotors and street pads are the right default; drilled rotors crack under track use, and race pads squeal and dust on the street.',
   'Greasy fingerprints on the new rotor cause judder — clean both faces. Do not let the caliper hang on the hose.',
   '["https://www.s2ki.com/forums/s2000-under-21-s2000-gt-technical-9/","https://www.stoptech.com/technical-support"]'::jsonb,
   '[]'::jsonb),

  ('Front brake pads and rotors', 'Ford', 'Focus ST', 2, 90, 180,
   '["13mm socket","15mm socket","ratchet","torque wrench","piston wind-back tool","brake cleaner","jack and stands"]'::jsonb,
   '[{"name":"Front pad set","est_cost_cents_low":5000,"est_cost_cents_high":12000,"part_number":null},{"name":"Front rotor pair","est_cost_cents_low":8000,"est_cost_cents_high":16000,"part_number":null}]'::jsonb,
   '["Lift the front and remove both wheels.","Remove the caliper guide-pin bolts and hang the caliper.","Unbolt the carrier, swap rotors after cleaning the hub.","Compress the piston, fit new pads with fresh clips.","Torque the carrier and guide pins to spec, refit wheels to 100 lb-ft.","Bed the pads with a series of moderate stops."]'::jsonb,
   'OEM-equivalent pads are quiet; one step up (a sport compound) resists fade on back roads at the cost of more dust.',
   'The Focus ST front piston pushes straight back — do not use a wind-back tool meant for rears. Retorque wheels after 50 miles.',
   '["https://www.focusst.org/forum/","https://www.focusst.org/forum/threads/brake-job-diy.12993/"]'::jsonb,
   '[]'::jsonb),

  ('Front brake pads and rotors', 'Toyota', '86', 2, 90, 180,
   '["14mm socket","17mm socket","ratchet","torque wrench","C-clamp","brake cleaner","jack and stands"]'::jsonb,
   '[{"name":"Front pad set","est_cost_cents_low":4500,"est_cost_cents_high":11000,"part_number":"SU003-04089"},{"name":"Front rotor pair","est_cost_cents_low":7000,"est_cost_cents_high":15000,"part_number":null}]'::jsonb,
   '["Lift the front, remove the wheels.","Pull the slide-pin bolts and hang the caliper.","Remove the carrier and rotor; clean the hub.","Compress the piston, fit the new pads and shims.","Reassemble and torque to spec, bed the pads in."]'::jsonb,
   'The 86 brakes are light-duty and cheap to service; pad upgrades matter more than rotor upgrades for street/track.',
   'The slide pins seize in rust-belt cars — regrease them. Check the pad-wear sensor wire when removing the inner pad.',
   '["https://www.ft86club.com/forums/","https://www.ft86club.com/forums/showthread.php?t=11057"]'::jsonb,
   '[]'::jsonb),

  ('Brake fluid flush', 'Subaru', 'WRX', 2, 60, 120,
   '["8mm or 10mm flare wrench","clear hose","catch bottle","jack and stands","turkey baster"]'::jsonb,
   '[{"name":"1 L DOT 4 brake fluid","est_cost_cents_low":1000,"est_cost_cents_high":2500,"part_number":null}]'::jsonb,
   '["Suck the reservoir down with the baster and refill with fresh fluid.","Start at the right-rear caliper: hose on the bleeder, crack it, have a helper pump, close on the downstroke.","Repeat left-rear, right-front, left-front until each runs clear.","Keep the reservoir above minimum the whole time.","Top off, check pedal firmness, and check for leaks at each bleeder."]'::jsonb,
   'High-boiling racing fluid (like RBF 600) helps on track but absorbs water faster — flush it yearly regardless of mileage.',
   'Letting the reservoir run dry pulls air into the ABS unit and turns a 1-hour job into a scan-tool bleed. Do not overtighten the bleeders; they snap.',
   '["https://forums.nasioc.com/forums/showthread.php?t=1684281","https://www.clubwrx.net/"]'::jsonb,
   '[]'::jsonb),

  ('Brake fluid flush', 'Mazda', 'MX-5 Miata', 2, 60, 120,
   '["10mm flare wrench","clear hose","catch bottle","jack and stands"]'::jsonb,
   '[{"name":"1 L DOT 4 brake fluid","est_cost_cents_low":1000,"est_cost_cents_high":2500,"part_number":null}]'::jsonb,
   '["Empty the reservoir and refill.","Bleed right-rear, left-rear, right-front, left-front with a two-person pump-and-hold.","Watch the reservoir level constantly.","Confirm a firm pedal and no bleeder leaks."]'::jsonb,
   'The NA/NB Miata has no ABS on most cars, so a basic two-person bleed is all it takes.',
   'Paint underneath the master cylinder strips instantly — wrap a rag around it and do not spill.',
   '["https://forum.miata.net/","https://www.miata.net/garage/"]'::jsonb,
   '[]'::jsonb),

  ('Coolant drain and refill', 'Honda', 'S2000', 2, 90, 150,
   '["drain pan","jack and stands","funnel","pliers for hose clamps"]'::jsonb,
   '[{"name":"1 gal Honda Type 2 coolant (pre-mixed)","est_cost_cents_low":1500,"est_cost_cents_high":2500,"part_number":null},{"name":"Radiator cap (if original)","est_cost_cents_low":800,"est_cost_cents_high":1500,"part_number":"19045-PCX-003"}]'::jsonb,
   '["With the engine cold, remove the radiator cap and open the block and radiator drains.","Drain fully, close the drains.","Refill slowly through the radiator neck, squeezing the upper hose to burp air.","Run the engine with the heater on full until the fans cycle, topping as it drops.","Fit the cap and fill the overflow to max."]'::jsonb,
   'Honda Type 2 is pre-mixed and cheap insurance; generic coolant works if it is silicate-free and mixed with distilled water.',
   'Trapped air overheats the F20C fast — burp it with the front raised and the heater on. Never open the cap hot.',
   '["https://www.s2ki.com/forums/s2000-under-21-s2000-gt-technical-9/"]'::jsonb,
   '[]'::jsonb),

  ('Coolant drain and refill', 'BMW', 'M3', 2, 120, 240,
   '["flathead screwdriver","drain pan","jack and stands","bleed screw tool"]'::jsonb,
   '[{"name":"2 gal BMW blue coolant concentrate","est_cost_cents_low":3000,"est_cost_cents_high":5000,"part_number":null},{"name":"2 gal distilled water","est_cost_cents_low":300,"est_cost_cents_high":600,"part_number":null}]'::jsonb,
   '["Cold engine: remove the expansion-tank cap and the radiator bleed screw.","Drain at the radiator petcock and the block drain.","Close drains, mix coolant 50/50 with distilled water.","Fill slowly, then run the electric water pump / engine with the bleed screw out until coolant flows bubble-free.","Top the expansion tank to the KALT mark."]'::jsonb,
   'E46 cooling systems are the weak point of the car; while draining, the expansion tank, thermostat, and water pump deserve a look — they are all service items.',
   'The bleed screw is plastic and shears — gentle pressure only. Skipping the bleed step air-locks the system.',
   '["https://www.e46fanatics.com/","https://www.bimmerforums.com/forum/showthread.php?1345639-Cooling-System-Overhaul-DIY"]'::jsonb,
   '[]'::jsonb),

  ('Spark plugs and coil packs', 'Honda', 'S2000', 2, 60, 120,
   '["10mm socket","5/8 spark plug socket","torque wrench","extensions","anti-seize","gap tool"]'::jsonb,
   '[{"name":"6 NGK PFR7G-11S plugs","est_cost_cents_low":6000,"est_cost_cents_high":10000,"part_number":"PFR7G-11S"},{"name":"Coil packs (replace as needed)","est_cost_cents_low":4000,"est_cost_cents_high":8000,"part_number":"30520-PCX-007"}]'::jsonb,
   '["Remove the coil-pack cover and the 10mm bolt on each coil.","Pull each coil straight up; inspect boots for oil.","Remove each plug, check the old plug''s color for running condition.","Gap and thread each new plug by hand, torque to 13 lb-ft.","Refit coils, bolts, and cover."]'::jsonb,
   'The AP1 uses six individual coils; replace only failed coils — a full set is a want, not a need. One heat range colder helps on track.',
   'Anti-seize on modern plated plugs is debated; if used, reduce torque. Cross-threading into the alloy head is the classic mistake.',
   '["https://www.s2ki.com/forums/s2000-under-21-s2000-gt-technical-9/","https://ngksparkplugs.com/"]'::jsonb,
   '[]'::jsonb),

  ('Spark plugs and coil packs', 'Volkswagen', 'Golf GTI', 2, 45, 90,
   '["10mm socket","spark plug socket 14mm thin-wall","torque wrench","extensions"]'::jsonb,
   '[{"name":"4 NGK plugs (stock heat range)","est_cost_cents_low":3500,"est_cost_cents_high":7000,"part_number":"06K905601B"},{"name":"Coil pack set (as needed)","est_cost_cents_low":6000,"est_cost_cents_high":12000,"part_number":null}]'::jsonb,
   '["Pull the engine cover and unplug each coil.","Slide each coil up off the plug.","Swap plugs one at a time, torqued to spec.","Refit coils until they click, then connectors."]'::jsonb,
   'Tuned EA888s like one step colder plugs and a tighter gap (~0.024 in); stock cars run the factory plug.',
   'A loose coil causes the misfire people blame on the plugs. Seat the coil until it clicks.',
   '["https://www.golfmk7.com/","https://www.vwvortex.com/"]'::jsonb,
   '[]'::jsonb),

  ('Spark plugs and coil packs', 'Nissan', '350Z', 2, 60, 120,
   '["10mm socket","14mm spark plug socket","ratchet","extensions","torque wrench"]'::jsonb,
   '[{"name":"6 NGK PLFR5A-11 plugs","est_cost_cents_low":5000,"est_cost_cents_high":9000,"part_number":"PLFR5A-11"}]'::jsonb,
   '["Remove the engine cover and unplug the three coils per side.","Unbolt and lift each coil.","Swap plugs one at a time with a wobble extension for the rear bank.","Torque plugs to spec, refit coils and connectors."]'::jsonb,
   'The VQ35DE is straightforward; the rear plugs need a wobble extension. Iridium plugs last ~100k.',
   'Do not drop anything into the plug well — pull the coil slowly and blow the well out first.',
   '["https://my350z.com/forum/","https://my350z.com/forum/engine-and-hybrid/"]'::jsonb,
   '[]'::jsonb),

  ('Differential fluid change', 'Toyota', '86', 1, 30, 60,
   '["10mm hex bit","ratchet","torque wrench","drain pan","fluid pump","jack and stands"]'::jsonb,
   '[{"name":"1.4 qt 75W-90 GL-5 gear oil","est_cost_cents_low":1500,"est_cost_cents_high":3500,"part_number":null},{"name":"2 drain/fill plug washers","est_cost_cents_low":200,"est_cost_cents_high":500,"part_number":null}]'::jsonb,
   '["Lift the rear level and remove the fill plug first.","Remove the drain plug and drain fully.","Refit the drain plug, pump in new oil until it weeps from the fill hole.","Torque both plugs to spec."]'::jsonb,
   'Any good GL-5 75W-90 works; LSD additives are unnecessary on the Torsen unit.',
   'Always break the fill plug loose before draining — a stuck fill plug with an empty diff strands the car.',
   '["https://www.ft86club.com/forums/","https://www.ft86club.com/forums/showthread.php?t=24552"]'::jsonb,
   '[]'::jsonb),

  ('Differential fluid change', 'Ford', 'Mustang', 1, 45, 90,
   '["3/8 ratchet (no plug)","drain pan","fluid pump","jack and stands","gasket scraper"]'::jsonb,
   '[{"name":"3 qt 75W-140 synthetic gear oil","est_cost_cents_low":2500,"est_cost_cents_high":4500,"part_number":null},{"name":"Friction modifier (8.8 Traction-Lok)","est_cost_cents_low":800,"est_cost_cents_high":1200,"part_number":null},{"name":"Cover gasket or RTV","est_cost_cents_low":500,"est_cost_cents_high":1500,"part_number":null}]'::jsonb,
   '["Lift the rear level, loosen the cover bolts, and drain through the bottom of the cover.","Remove the cover, clean the mating faces.","Refit with a new gasket or a thin RTV bead, bolts to spec in a cross pattern.","Fill through the cover hole or fill plug with 75W-140 plus friction modifier until it weeps."]'::jsonb,
   'The Fox/SN95 8.8 has no drain plug — the cover comes off. Friction modifier stops clutch-pack chatter on Traction-Lok diffs.',
   'Too much RTV squeezes into the housing. Skipping friction modifier gives a parking-lot shudder.',
   '["https://www.mustang6g.com/","https://www.stangnet.com/mustang-forums/"]'::jsonb,
   '[]'::jsonb),

  ('Differential fluid change', 'Nissan', '240SX', 1, 30, 60,
   '["1/2 inch breaker bar or plug socket","drain pan","fluid pump","jack and stands"]'::jsonb,
   '[{"name":"1.7 qt 75W-90 GL-5 gear oil","est_cost_cents_low":1500,"est_cost_cents_high":3500,"part_number":null}]'::jsonb,
   '["Lift the rear level; loosen the fill plug first.","Drain through the bottom plug.","Pump 75W-90 in until it weeps from the fill hole, refit both plugs to spec."]'::jsonb,
   'The S13/S14 VLSD wants a GL-5 that is LSD-safe; a welded diff does not care.',
   'The plugs are tapered and get very tight — crack them before lifting the car so you can lean on the bar.',
   '["https://zilvia.net/f/","https://forums.nicoclub.com/"]'::jsonb,
   '[]'::jsonb),

  ('Battery replacement', 'Volkswagen', 'Jetta', 1, 20, 45,
   '["10mm wrench","13mm socket","battery terminal brush"]'::jsonb,
   '[{"name":"Group 48/H6 battery","est_cost_cents_low":12000,"est_cost_cents_high":22000,"part_number":null}]'::jsonb,
   '["Ignition off: disconnect negative first, then positive.","Remove the hold-down and lift the battery straight up.","Clean the tray and terminals, fit the new battery, hold-down snug.","Connect positive, then negative; reset the clock and one-touch windows."]'::jsonb,
   'Match the group size and CCA; Mk4 cars do not need battery coding, newer VWs do.',
   'Negative off first and on last — a wrench that touches ground on the positive terminal will arc.',
   '["https://www.tdiclub.com/","https://www.vwvortex.com/"]'::jsonb,
   '[]'::jsonb),

  ('Battery replacement', 'MINI', 'Cooper S', 1, 45, 90,
   '["10mm wrench","13mm socket","trim tool","torx driver"]'::jsonb,
   '[{"name":"Group 47/H5 AGM battery","est_cost_cents_low":18000,"est_cost_cents_high":32000,"part_number":null}]'::jsonb,
   '["The R53/R56 battery sits under the cowl or in the boot — remove the trim.","Disconnect negative, then positive; remove the hold-down.","Swap the battery, vent tube reconnected if fitted.","Reconnect positive, then negative; register the battery on 2007+ cars."]'::jsonb,
   'AGM is required where fitted — a flooded battery in its place dies early. Battery registration on newer cars keeps charging strategy correct.',
   'Forgetting the vent tube corrodes the boot floor. Losing radio presets is the least of it — unregistered batteries overcharge.',
   '["https://www.northamericanmotoring.com/forums/","https://www.mini2.com/"]'::jsonb,
   '[]'::jsonb),

  ('Tires and alignment', 'Toyota', '86', 1, 60, 120,
   '["torque wrench","jack and stands","tread gauge"]'::jsonb,
   '[{"name":"Set of 4 tires (215/45R17)","est_cost_cents_low":45000,"est_cost_cents_high":90000,"part_number":null},{"name":"4-wheel alignment","est_cost_cents_low":10000,"est_cost_cents_high":15000,"part_number":null}]'::jsonb,
   '["Pick tires for the use: 200tw for track/autocross, all-season for year-round.","Have a shop mount and balance; torque wheels to 76 lb-ft.","Alignment: stock street spec is roughly zero toe, about -1.0 to -1.5 degrees camber front.","Ask for a printout of before/after numbers."]'::jsonb,
   'The 86 was designed around a grippy-but-narrow tire; wider rubber helps grip but adds tramlining and needs real negative camber to work.',
   'Alignment shops that set toe ''to spec'' often center the range badly — ask for slight toe-out front for turn-in on a weekend car, zero toe for tire life.',
   '["https://www.ft86club.com/forums/","https://www.tirerack.com/"]'::jsonb,
   '["wheels_light"]'::jsonb),

  ('Tires and alignment', 'Ford', 'Focus RS', 1, 60, 120,
   '["torque wrench","jack and stands"]'::jsonb,
   '[{"name":"Set of 4 tires (235/35R19)","est_cost_cents_low":60000,"est_cost_cents_high":110000,"part_number":null},{"name":"4-wheel alignment","est_cost_cents_low":10000,"est_cost_cents_high":15000,"part_number":null}]'::jsonb,
   '["Mount and balance; torque to 100 lb-ft.","Alignment: the RS torque-steers with excess front camber — keep it near -1.5 degrees, slight toe-in.","Verify the rear toe; the RS rear end is sensitive.","Road-force balance if there is any vibration."]'::jsonb,
   'The stock Pilot Super Sport is good; a 200tw tire transforms the car for track but kills wet grip and wear.',
   'A bad alignment amplifies the RS''s torque steer and inner-edge wear. Check tire pressures after the shop — they often overinflate.',
   '["https://www.focusrs.org/","https://www.tirerack.com/"]'::jsonb,
   '["wheels_light"]'::jsonb),

  ('Cold air intake install', 'Subaru', 'WRX', 2, 60, 120,
   '["8mm socket","10mm socket","flathead screwdriver","pliers"]'::jsonb,
   '[{"name":"Cold air intake kit","est_cost_cents_low":25000,"est_cost_cents_high":45000,"part_number":null},{"name":"MAF-safe panel filter (if needed)","est_cost_cents_low":3000,"est_cost_cents_high":6000,"part_number":null}]'::jsonb,
   '["Disconnect the battery, remove the snorkus and airbox.","Transfer the MAF sensor to the new intake tube without touching the element.","Fit the intake, route the filter to the fender well, tighten clamps.","Refit the undertray and reconnect the battery."]'::jsonb,
   'On the FA cars an intake alone is near zero power and can lean the tune; an off-the-shelf map for the intake matters more than the pipe.',
   'Running an intake that needs a tune on the stock map risks knock. Oiled filters coat the MAF — dry filters or light oil only.',
   '["https://forums.nasioc.com/","https://www.clubwrx.net/","https://www.cobbtuning.com/support/"]'::jsonb,
   '["intake_cai_turbo"]'::jsonb),

  ('Cold air intake install', 'Volkswagen', 'Golf GTI', 2, 45, 90,
   '["T25 Torx","flathead screwdriver","8mm socket"]'::jsonb,
   '[{"name":"Intake kit","est_cost_cents_low":25000,"est_cost_cents_high":50000,"part_number":null}]'::jsonb,
   '["Remove the engine cover and stock airbox lid.","Fit the new intake pipe and heat shield, transfer the MAF housing if needed.","Clamp everything snug, refit hoses, and check clearances at full lock."]'::jsonb,
   'The EA888 intake is mostly a noise mod — open filters sound great but pull hot air at low speed. A closed box with a panel filter is the quieter compromise.',
   'A loose MAF connector throws a lean code. Check the turbo-inlet pipe while you are in there — the plastic one is a known weak point.',
   '["https://www.golfmk7.com/","https://www.vwvortex.com/"]'::jsonb,
   '["intake_cai_turbo"]'::jsonb),

  ('Cold air intake install', 'Honda', 'Civic Type R', 2, 45, 90,
   '["10mm socket","flathead screwdriver","trim tool"]'::jsonb,
   '[{"name":"Intake kit","est_cost_cents_low":30000,"est_cost_cents_high":55000,"part_number":null}]'::jsonb,
   '["Remove the front intake duct and airbox.","Fit the new box/pipe, transfer the MAF, clamp everything.","Check for rubbing at the battery tray and refit the duct."]'::jsonb,
   'The FK8 gains little from an intake alone; the draw is turbo noise. Paired with a downpipe and tune it completes the bolt-on path.',
   'Aftermarket MAF housings with a different diameter need a matching tune — running one on the stock calibration leans the car.',
   '["https://www.civicx.com/forum/","https://www.civicx.com/forum/threads/intake-install.15342/"]'::jsonb,
   '["intake_cai_turbo"]'::jsonb),

  ('Cat-back exhaust install', 'Honda', 'S2000', 3, 120, 240,
   '["12mm socket","14mm socket","ratchet","extensions","exhaust hanger tool","penetrating oil","jack and stands","torque wrench"]'::jsonb,
   '[{"name":"Cat-back exhaust","est_cost_cents_low":60000,"est_cost_cents_high":150000,"part_number":null},{"name":"Exhaust gaskets","est_cost_cents_low":1000,"est_cost_cents_high":3000,"part_number":"18229-S2A-000"},{"name":"New flange nuts/bolts","est_cost_cents_low":800,"est_cost_cents_high":2000,"part_number":null}]'::jsonb,
   '["Soak the flange bolts and hanger rubbers in penetrating oil the night before.","Lift the rear, support the muffler, unbolt the flange behind the cat.","Pull the hangers off their posts one at a time and lower the system.","Transfer hangers, offer the new system up loose, align the tips.","Torque the flange bolts with new gaskets and hardware.","Start it and check for leaks with a hand near each joint."]'::jsonb,
   'A single-exit cat-back saves ~15 lb and adds sound; a dual keeps the stock look. Neither adds real power on an F20C — it is a sound and weight mod.',
   'Overtightening the flange crushes the gasket and it leaks anyway. Cheap systems drone at 4k — listen to a car before buying.',
   '["https://www.s2ki.com/forums/s2000-talk-1/","https://www.s2ki.com/s2000/topic/"]'::jsonb,
   '["catback","exhaust_ti"]'::jsonb),

  ('Cat-back exhaust install', 'Nissan', '350Z', 3, 120, 240,
   '["14mm socket","ratchet","extensions","hanger tool","penetrating oil","jack and stands","torque wrench"]'::jsonb,
   '[{"name":"Cat-back exhaust","est_cost_cents_low":50000,"est_cost_cents_high":120000,"part_number":null},{"name":"Gaskets and hardware","est_cost_cents_low":1500,"est_cost_cents_high":4000,"part_number":null}]'::jsonb,
   '["Soak fasteners overnight; the DE rusts them solid.","Unbolt at the rear of the cats and pull the mid-pipe and muffler as sections.","Fit the new mid-pipe then muffler loose, align, then torque.","Check for leaks and tip alignment after heat cycling."]'::jsonb,
   'Single-exit systems cut real weight on the Z. True-dual systems keep backpressure balance; a Y-pipe single is louder for less money.',
   'Rusted flange studs snap — budget time for the drill. A slight tip misalignment bugs you forever; fit it all loose first.',
   '["https://my350z.com/forum/"]'::jsonb,
   '["catback"]'::jsonb),

  ('Cat-back exhaust install', 'Ford', 'Mustang', 3, 120, 240,
   '["13mm socket","15mm socket","ratchet","hanger tool","penetrating oil","jack and stands"]'::jsonb,
   '[{"name":"Cat-back or axle-back system","est_cost_cents_low":40000,"est_cost_cents_high":120000,"part_number":null}]'::jsonb,
   '["Axle-back on a Fox: unbolt at the flow tubes, cut nothing on the stock system yet.","Slide the mufflers off the hangers, transfer the rubbers.","Fit tailpipes, check tip alignment in the bumper cutouts, then tighten."]'::jsonb,
   'On a 5.0 Fox the sound is the whole point — a cat-back with an H-pipe keeps the classic tone; straight-through mufflers drone at cruise.',
   'Tailpipe tips that touch the bumper melt plastic and rattle. Keep the cat pipe if the car has emissions inspection.',
   '["https://www.stangnet.com/mustang-forums/","https://www.mustang6g.com/"]'::jsonb,
   '["catback","axleback","h_pipe"]'::jsonb),

  ('Downpipe install', 'Subaru', 'WRX', 4, 180, 360,
   '["12mm socket","14mm socket","17mm socket","ratchet","swivel extensions","penetrating oil","jack and stands","torque wrench","O2 sensor socket"]'::jsonb,
   '[{"name":"Catted downpipe","est_cost_cents_low":40000,"est_cost_cents_high":90000,"part_number":null},{"name":"Up-pipe/downpipe gaskets","est_cost_cents_low":1500,"est_cost_cents_high":4000,"part_number":null}]'::jsonb,
   '["Disconnect the battery; soak every fastener.","Remove the intercooler or heat shield for access.","Unbolt the downpipe from the turbo and mid-pipe, transfer the O2 sensors.","Fit the new pipe with new gaskets, torque from the turbo back.","Flash the matching tune before driving — do not run a downpipe on the stock map."]'::jsonb,
   'A catted downpipe keeps it streetable and legal-ish; catless is louder, smells, and fails visual inspection. The power is real either way — with the tune.',
   'The downpipe without a tune is the classic blown-ringland story on EJ cars and a lean-risk on FA. Snapped turbo studs are common; heat and patience beat force.',
   '["https://forums.nasioc.com/","https://www.clubwrx.net/","https://www.cobbtuning.com/support/"]'::jsonb,
   '["downpipe"]'::jsonb),

  ('Downpipe install', 'Volkswagen', 'Golf GTI', 4, 180, 360,
   '["16mm socket","18mm socket","ratchet","swivel extensions","penetrating oil","jack and stands","O2 sensor socket","torque wrench"]'::jsonb,
   '[{"name":"Catted downpipe","est_cost_cents_low":45000,"est_cost_cents_high":100000,"part_number":null},{"name":"Downpipe gasket and clamps","est_cost_cents_low":1500,"est_cost_cents_high":4000,"part_number":null}]'::jsonb,
   '["Soak the V-band and subframe-area bolts.","Support the engine, drop the subframe enough to angle the pipe out.","Transfer both O2 sensors with anti-seize on the threads only.","Fit the new pipe, torque the V-band evenly.","Flash the stage-2 map before driving."]'::jsonb,
   'The EA888 downpipe is the single biggest bolt-on gain. Catted flows nearly as well as catless and keeps the car honest.',
   'Sensor threads get anti-seize on the threads, never on the tip. Rattles against the subframe mean the pipe is not seated in its bracket.',
   '["https://www.golfmk7.com/","https://www.vwvortex.com/"]'::jsonb,
   '["downpipe"]'::jsonb),

  ('Stage 1 tune (ECU flash)', 'Volkswagen', 'Golf GTI', 1, 30, 60,
   '["laptop or accessport","battery maintainer"]'::jsonb,
   '[{"name":"Stage 1 tune / accessport","est_cost_cents_low":45000,"est_cost_cents_high":70000,"part_number":null}]'::jsonb,
   '["Attach a battery maintainer — a voltage drop mid-flash bricks the ECU.","Read and save the stock map first.","Flash the stage-1 map matching your octane.","Log a few pulls and watch for knock corrections."]'::jsonb,
   'Stage 1 is the best money-per-hp on the EA888: roughly +40-60 hp on 93. A warranty-friendly option is a piggyback you can remove before service.',
   'Flashing without a maintainer, or flashing a map that does not match your octane. Keep the stock file; dealers do notice.',
   '["https://www.golfmk7.com/","https://www.goapr.com/","https://www.cobbtuning.com/"]'::jsonb,
   '["tune_s1_turbo"]'::jsonb),

  ('Stage 1 tune (ECU flash)', 'Subaru', 'Impreza WRX STI', 1, 30, 60,
   '["accessport or laptop","battery maintainer"]'::jsonb,
   '[{"name":"Stage 1 map / accessport","est_cost_cents_low":50000,"est_cost_cents_high":75000,"part_number":null}]'::jsonb,
   '["Maintainer on the battery, laptop closed on a stable surface.","Back up the stock calibration.","Flash the stage-1 93-octane map, confirm no CEL.","Data-log boost and knock on the first drive."]'::jsonb,
   'The EJ257 responds modestly to stage 1 — the gain is throttle feel and midrange. EJ owners should log religiously; these engines give warning before they go.',
   'Running 91 octane on a 93 map, or skipping logs. A stage-2 map without the downpipe overboosts.',
   '["https://forums.nasioc.com/","https://www.clubwrx.net/"]'::jsonb,
   '["tune_s1_turbo"]'::jsonb),

  ('Lowering springs install', 'Toyota', '86', 3, 240, 420,
   '["spring compressors","socket set","breaker bar","torque wrench","jack and stands","penetrating oil"]'::jsonb,
   '[{"name":"Lowering spring set","est_cost_cents_low":25000,"est_cost_cents_high":40000,"part_number":null},{"name":"Alignment (after)","est_cost_cents_low":10000,"est_cost_cents_high":15000,"part_number":null}]'::jsonb,
   '["Lift the car and remove the wheels; mark camber bolts.","Support the knuckle, unbolt the strut from the knuckle and top hat.","Compress the spring, swap it, reassemble the strut.","Repeat all four corners, torque everything, then get an alignment."]'::jsonb,
   'Springs drop ~1 inch for cheap and keep ride close to stock; coilovers cost 4x but add damping matched to the rate and height adjustability.',
   'Lowering on stock dampers wears them out within a year or two. Never skip the alignment — the drop adds camber and eats inner edges.',
   '["https://www.ft86club.com/forums/","https://www.ft86club.com/forums/showthread.php?t=18965"]'::jsonb,
   '[]'::jsonb),

  ('Coilover install', 'BMW', 'M3', 4, 300, 480,
   '["socket set","breaker bar","torque wrench","jack and stands","spanners for collars","penetrating oil","spring compressors"]'::jsonb,
   '[{"name":"Coilover kit","est_cost_cents_low":120000,"est_cost_cents_high":300000,"part_number":null},{"name":"Camber plates (optional)","est_cost_cents_low":20000,"est_cost_cents_high":40000,"part_number":null},{"name":"Alignment","est_cost_cents_low":10000,"est_cost_cents_high":15000,"part_number":null}]'::jsonb,
   '["Lift and strip one corner at a time: wheel, drop link, knuckle bolts, top hat.","Assemble the coilover at a baseline height and preload it per the manual.","Fit, torque to spec, set ride height equal left-to-right.","Drive 50 miles to settle, re-check height, then corner-balance and align."]'::jsonb,
   'Street coilovers with matched dampers beat cut springs on every measure. Camber plates add front camber the drop removes the ability to set.',
   'Ride height by eye is never equal; measure hub-to-fender. Seized collar threads mean the kit dies early — anti-seize them on day one.',
   '["https://www.e46fanatics.com/","https://www.bimmerforums.com/forum/"]'::jsonb,
   '[]'::jsonb),

  ('Coilover install', 'Honda', 'Civic', 3, 240, 420,
   '["socket set","breaker bar","torque wrench","jack and stands","spanners","penetrating oil"]'::jsonb,
   '[{"name":"Coilover kit","est_cost_cents_low":80000,"est_cost_cents_high":180000,"part_number":null},{"name":"Alignment","est_cost_cents_low":10000,"est_cost_cents_high":15000,"part_number":null}]'::jsonb,
   '["Strip each corner: wheel, ABS line bracket, knuckle bolts, top hat nuts.","Preset height and preload, install, torque.","Settle, level the heights, align."]'::jsonb,
   'On an EJ8 the Koni yellow + Ground Control combo is the budget classic; a full name-brand kit rides and adjusts better for more money.',
   'Slamming a Civic kills travel and tears CV boots — an inch and a half is the sweet spot. Max-low is for photos, not driving.',
   '["https://www.honda-tech.com/forums/","https://honda-tech.com/forums/honda-civic-eg-eh-ej-92-00-a-56/"]'::jsonb,
   '[]'::jsonb),

  ('Sway bar install', 'Mazda', 'MX-5 Miata', 2, 90, 180,
   '["12mm socket","14mm socket","ratchet","torque wrench","jack and stands","grease"]'::jsonb,
   '[{"name":"Front sway bar","est_cost_cents_low":15000,"est_cost_cents_high":35000,"part_number":null},{"name":"Poly bushings and end links","est_cost_cents_low":5000,"est_cost_cents_high":12000,"part_number":null}]'::jsonb,
   '["Lift the front and remove the wheels for access.","Unbolt the end links and bushing brackets, slide the bar out.","Grease the new bushings, fit the bigger bar, new links.","Torque brackets and links, set the bar on the softest hole first."]'::jsonb,
   'A bigger front bar on a Miata dials in understeer — most drivers want the rear bar stiffer or the front adjustable to tune balance. Adjustable end links matter once lowered.',
   'Preloading the links with the suspension drooped twists the bushing — tighten links at ride height. A bar that is too stiff makes the car skate mid-corner.',
   '["https://forum.miata.net/","https://www.miata.net/garage/","https://flyinmiata.com/"]'::jsonb,
   '[]'::jsonb),

  ('Sway bar install', 'Subaru', 'WRX', 2, 90, 180,
   '["12mm socket","14mm socket","ratchet","torque wrench","jack and stands"]'::jsonb,
   '[{"name":"Rear sway bar (stiffer)","est_cost_cents_low":12000,"est_cost_cents_high":30000,"part_number":null},{"name":"End links","est_cost_cents_low":4000,"est_cost_cents_high":10000,"part_number":null}]'::jsonb,
   '["Lift the rear, support the subframe.","Unbolt the end links and brackets, drop the bar over the exhaust.","Fit the stiffer bar with greased bushings, set to the middle hole.","Torque at ride height."]'::jsonb,
   'The classic WRX setup is a stiffer rear bar only — it loosens the tail and keeps the front planted. Bigger both ends flattens the car but dumbs the balance.',
   'The rear bar comes out over the exhaust — let it cool. End links on a lowered car need to be adjustable length or they bind.',
   '["https://forums.nasioc.com/","https://www.clubwrx.net/"]'::jsonb,
   '[]'::jsonb),

  ('Short shifter install', 'Toyota', 'Corolla', 2, 60, 120,
   '["12mm socket","needle-nose pliers","trim tool","grease"]'::jsonb,
   '[{"name":"Short shifter kit","est_cost_cents_low":8000,"est_cost_cents_high":20000,"part_number":null},{"name":"Shifter base bushings","est_cost_cents_low":1500,"est_cost_cents_high":4000,"part_number":null}]'::jsonb,
   '["Pull the center console trim and shift boot.","Unclip the AE86 shifter retainer and lift the lever.","Fit the short lever with fresh grease and the new bushings.","Seat the retainer, refit trim, and check every gear engages."]'::jsonb,
   'A short throw on a 4AGE car is all feel — shorter lever, new bushings. The T50 is not precise to begin with; bushings do more than the lever.',
   'A dry pivot wears the seat in weeks — pack it with lithium grease. Forcing reverse with a mis-seated retainer chips the gate.',
   '["https://club4ag.com/","https://www.ae86drivingclub.com.au/"]'::jsonb,
   '[]'::jsonb),

  ('Fuel filter replacement', 'Honda', 'Civic', 2, 45, 90,
   '["10mm flare wrench","12mm flare wrench","line plugs","rags","eye protection"]'::jsonb,
   '[{"name":"Fuel filter","est_cost_cents_low":1500,"est_cost_cents_high":3500,"part_number":"16010-ST5-E02"}]'::jsonb,
   '["Depressurize: pull the fuel-pump fuse and crank briefly.","Unbolt the bracket, flare-wrench both banjo fittings — one side turns, one holds.","Swap the filter (arrow to the engine), new crush washers on the banjo.","Refit the fuse, key to ON a few times, check for leaks."]'::jsonb,
   'EG/EK filters are cheap insurance every 60k; most owners never touch them.',
   'Fuel sprays even after depressurizing — rags and glasses on. Reusing crush washers seeps.',
   '["https://www.honda-tech.com/forums/","https://honda-tech.com/forums/honda-civic-eg-eh-ej-92-00-a-56/"]'::jsonb,
   '[]'::jsonb),

  ('Radiator replacement', 'Toyota', 'Corolla', 3, 120, 240,
   '["10mm socket","pliers","drain pan","jack and stands","funnel"]'::jsonb,
   '[{"name":"Radiator","est_cost_cents_low":8000,"est_cost_cents_high":20000,"part_number":null},{"name":"Upper and lower hoses","est_cost_cents_low":2500,"est_cost_cents_high":6000,"part_number":null},{"name":"1 gal coolant","est_cost_cents_low":1500,"est_cost_cents_high":2500,"part_number":null}]'::jsonb,
   '["Drain the coolant, remove the upper and lower hoses and the fan shroud.","Unbolt the radiator brackets and lift it out.","Transfer the fan and shroud to the new unit, drop it in.","Hoses on with new clamps, refill, and burp the system with the heater on."]'::jsonb,
   'A 30-year-old AE86 radiator with crusted tanks is on borrowed time; an aluminum unit is an upgrade, a stock replacement is fine.',
   'Forcing old hoses tears them — cut them if they fight. An air pocket cooks a 4AGE quickly, so burp it raised.',
   '["https://club4ag.com/","https://www.ae86drivingclub.com.au/"]'::jsonb,
   '[]'::jsonb),

  ('Clutch fluid flush', 'Honda', 'S2000', 1, 30, 60,
   '["8mm flare wrench","clear hose","catch bottle","turkey baster"]'::jsonb,
   '[{"name":"Small bottle DOT 3/4 fluid","est_cost_cents_low":600,"est_cost_cents_high":1200,"part_number":null}]'::jsonb,
   '["Baster the clutch reservoir down and refill with fresh fluid.","Hose on the slave bleeder, crack it, pump the pedal slowly, close on the stroke.","Repeat until clean; keep the reservoir above min.","Confirm a crisp pedal return."]'::jsonb,
   'The S2000 shares fluid type with the brakes; a yearly syringe swap on the reservoir alone helps.',
   'A spongy pedal after a flush is air in the slave — keep bleeding, do not assume the clutch is gone.',
   '["https://www.s2ki.com/forums/s2000-under-21-s2000-gt-technical-9/"]'::jsonb,
   '[]'::jsonb),

  ('PCV valve and hoses', 'Mitsubishi', 'Lancer Evolution', 2, 60, 120,
   '["10mm socket","pliers","flathead screwdriver","rags"]'::jsonb,
   '[{"name":"PCV valve","est_cost_cents_low":800,"est_cost_cents_high":2000,"part_number":"1035A422"},{"name":"PCV hose","est_cost_cents_low":1000,"est_cost_cents_high":3000,"part_number":null}]'::jsonb,
   '["Remove the intercooler pipe for access to the valve cover.","Pull the PCV valve and hose; shake the valve — it should rattle.","Fit the new valve and hose with fresh clamps.","Refit the pipe and check for boost leaks."]'::jsonb,
   'A stuck PCV on a boosted 4G63 pressurizes the crankcase and pushes oil everywhere it should not be.',
   'The hose hardens and splits under the manifold — replace both together. Cheap valves leak boost into the crankcase.',
   '["https://www.evolutionm.net/forums/","https://www.evolutionm.net/forums/evo-x-general/"]'::jsonb,
   '[]'::jsonb),

  ('Serpentine belt and tensioner', 'BMW', '318is', 2, 60, 120,
   '["16mm socket or belt tool","ratchet","breaker bar"]'::jsonb,
   '[{"name":"Serpentine belt","est_cost_cents_low":2000,"est_cost_cents_high":4000,"part_number":null},{"name":"Tensioner assembly","est_cost_cents_low":4000,"est_cost_cents_high":9000,"part_number":null}]'::jsonb,
   '["Sketch the belt routing before touching anything.","Release the tensioner with the tool and slip the belt off.","If the tensioner bearing has play, swap the unit.","Route the new belt per the sketch, release the tensioner slowly."]'::jsonb,
   'On a 30-year-old E30 the belt and tensioner are a pair — the tensioner bearing outlives nothing.',
   'A belt routed over the wrong side of an idler self-destructs in minutes. Check the routing twice before starting it.',
   '["https://www.r3vlimited.com/board/","https://www.e30zone.net/e30wiki/"]'::jsonb,
   '[]'::jsonb),

  ('Manual transmission fluid change', 'Honda', 'S2000', 1, 30, 60,
   '["3/8 ratchet","17mm hex or square plug socket","drain pan","fluid pump","jack and stands"]'::jsonb,
   '[{"name":"2.2 qt Honda MTF","est_cost_cents_low":2000,"est_cost_cents_high":4000,"part_number":null},{"name":"Washers","est_cost_cents_low":200,"est_cost_cents_high":500,"part_number":null}]'::jsonb,
   '["Lift the car level; loosen the fill plug first.","Drain through the bottom plug.","Pump in Honda MTF until it weeps from the fill hole.","Torque both plugs to spec."]'::jsonb,
   'Honda MTF is the right answer; GM synchromesh is the popular alternative for notchiness on AP2 transmissions.',
   'The AP2 2nd-gear grind often improves with fresh fluid — it is the cheapest fix to try first.',
   '["https://www.s2ki.com/forums/s2000-under-21-s2000-gt-technical-9/"]'::jsonb,
   '[]'::jsonb),

  ('Intercooler piping refresh', 'Mitsubishi', 'Lancer Evolution', 3, 120, 240,
   '["flathead screwdriver","8mm socket","10mm socket","brake cleaner","rags"]'::jsonb,
   '[{"name":"Silicone coupler set","est_cost_cents_low":8000,"est_cost_cents_high":20000,"part_number":null},{"name":"T-bolt clamps","est_cost_cents_low":3000,"est_cost_cents_high":8000,"part_number":null}]'::jsonb,
   '["Pull the upper and lower IC pipes; check inside for oil film.","Clean every joint face with brake cleaner.","Fit new couplers and T-bolt clamps, snug but not crushing.","Boost-leak test or log a pull for lost boost."]'::jsonb,
   'The 4G63/4B11 pushes enough boost to blow tired rubber couplers; silicone and T-bolts fix it permanently.',
   'Oil inside the pipes is normal blow-by — a lot of it means check the PCV. Clamps over-tightened cut the silicone.',
   '["https://www.evolutionm.net/forums/"]'::jsonb,
   '["intercooler","charge_pipe"]'::jsonb)
;
